                            pur = float(val)
                            net = pur
                            break
                    except Exception:
                        pass

            if pur <= 0 or net <= 0:
                try:
                    se_rate = frappe.db.sql("""
                        SELECT basic_rate FROM `tabStock Entry Detail`
                        WHERE batch_no = %s AND docstatus = 1 AND basic_rate > 0
