        raw = per_day(x.dosage) * days(x.period)
        units = int(raw)
        if raw > units:
            units += 1
        drugs.append({"drug": x.drug_code, "item": item, "item_name": item_name,
            "dosage": x.dosage or "", "period": x.period or "", "comment": x.comment or "",
            "units": units})
