def num(v):
    try:
        return float(v or 0)
    except:
        return 0.0

def wh_qty(b, w):
    try:
        r = frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=b, warehouse=w)
    except:
        return None
    try:
        return float(r)
    except:
        pass
    try:
        t = 0
        for x in r:
            t += x.get("qty") or 0
        return t
    except:
        return None

f = frappe.form_dict
bname = (f.get("batch") or "").strip()
wh = f.get("warehouse")
if not bname or not frappe.db.exists("Batch", bname):
    frappe.throw("That batch was not found.")
if not wh:
    frappe.throw("Choose a store.")
if not f.get("expiry"):
    frappe.throw("Enter the batch expiry.")

today_str = str(frappe.utils.today())
today_date = frappe.utils.getdate(today_str)
posting_date = (f.get("posting_date") or "").strip()
if posting_date:
    try:
        p_date = frappe.utils.getdate(posting_date)
    except Exception:
        frappe.throw("Invalid posting date.")
    if p_date < today_date and not is_admin:
        frappe.throw("Only admin accounts can create backdated stock entries.")

upp = int(num(f.get("upp")))
if upp < 1:
    upp = 1
gst = num(f.get("gst"))
rate = num(f.get("rate"))
if f.get("basis") == "incl":
    rate = rate / (1 + gst / 100)
qty = num(f.get("packs")) * upp + num(f.get("units"))
if qty < 0:
    frappe.throw("Quantity cannot be negative.")

company = frappe.db.get_single_value("Global Defaults", "default_company")
co = frappe.db.get_value("Company", company, ["stock_adjustment_account", "cost_center"], as_dict=True) or {}
adj_acc = co.get("stock_adjustment_account")
if not adj_acc:
    adj_acc = frappe.db.get_value("Account", {"account_type": "Stock Adjustment", "company": company, "is_group": 0}, "name")
if not adj_acc:
    adj_acc = frappe.db.get_value("Account", {"account_name": ["like", "%Stock Adjustment%"], "company": company, "is_group": 0}, "name")
if not adj_acc:
    adj_acc = frappe.db.get_value("Company", company, "default_inventory_account")

cost_center = co.get("cost_center")
if not cost_center:
    cost_center = frappe.db.get_value("Cost Center", {"company": company, "is_group": 0}, "name")

b = frappe.get_doc("Batch", bname)
item = b.item
old_rate = b.purchase_rate or 0
meta = frappe.get_meta("Batch")
if f.get("expiry"):
    b.expiry_date = f.get("expiry")
hsn = f.get("hsn") or ""
mrp = num(f.get("mrp"))
net = rate if ((not b.net_rate) or abs(rate - old_rate) > 0.0001) else (b.net_rate or rate)

for fn, val in [("hsn_code", hsn), ("gst_rate", gst), ("mrp", mrp),
                ("purchase_rate", rate), ("net_rate", net), ("units_per_pack", upp)]:
    if meta.has_field(fn):
        b.set(fn, val)
    if meta.has_field("custom_" + fn):
        b.set("custom_" + fn, val)
b.save(ignore_permissions=True)

cur = wh_qty(bname, wh)
if cur is None:
    try:
        s = frappe.db.sql("""select sum(actual_qty) from `tabStock Ledger Entry`
            where batch_no = %s and warehouse = %s and is_cancelled = 0""", (bname, wh))
        if s and s[0] and s[0][0] is not None:
            cur = float(s[0][0])
    except:
        pass
if cur is None:
    cur = frappe.db.get_value("Batch", bname, "batch_qty") or 0
val = rate / upp
doc_name = ""
if qty != cur:
    if cur <= 0:
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Receipt"
        se.purpose = "Material Receipt"
        se.company = company
        se.to_warehouse = wh
        if posting_date:
            se.posting_date = posting_date
            se.set_posting_time = 1
        se.append("items", {"item_code": item, "qty": qty, "t_warehouse": wh, "basic_rate": val,
            "batch_no": bname, "use_serial_batch_fields": 1,
            "expense_account": adj_acc, "cost_center": cost_center})
        se.insert(ignore_permissions=True)
        se.submit()
        doc_name = se.name
    else:
        sr = frappe.new_doc("Stock Reconciliation")
        sr.purpose = "Stock Reconciliation"
        sr.company = company
        if posting_date:
            sr.posting_date = posting_date
            sr.set_posting_time = 1
        sr.expense_account = adj_acc
        sr.cost_center = cost_center
        sr.append("items", {"item_code": item, "warehouse": wh, "qty": qty, "valuation_rate": val,
            "batch_no": bname, "use_serial_batch_fields": 1})
        sr.insert(ignore_permissions=True)
        sr.submit()
        doc_name = sr.name

frappe.response["message"] = {"batch": bname, "units": qty, "upp": upp, "document": doc_name}

# Server Script: ph_stock_list
# type: API
# doctype: -
# event: Before Insert
# api_method: ph_stock_list
# allow_guest: 0
# frequency: All
# disabled: 0

ok = False
for r in ["Stock User", "Stock Manager", "Accounts User", "Sales User", "Purchase User", "System Manager"]:
    if frappe.db.exists("Has Role", {"parent": frappe.session.user, "role": r}):
        ok = True
if not ok:
    frappe.throw("You don't have access to the pharmacy.")

def wh_qty(b, w):
    try:
        r = frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=b, warehouse=w)
        if isinstance(r, (int, float)):
            return float(r)
        if isinstance(r, list):
            return sum(float(x.get("qty") or 0) for x in r)
    except:
        pass
    try:
        res = frappe.db.sql("""select sum(actual_qty) from `tabStock Ledger Entry`
            where batch_no = %s and warehouse = %s and is_cancelled = 0""", (b, w))
        if res and res[0] and res[0][0] is not None:
            return float(res[0][0])
    except:
        pass
    return None

def parse_upp_from_name(name):
    if not name:
        return 1
    clean = str(name).lower().replace("'", " ").replace("(", " ").replace(")", " ").replace("/", " ")
    words = clean.split()
    for w in words:
        if w.endswith("s") and len(w) > 1 and w[:-1].isdigit():
            val = int(w[:-1])
            if 1 < val <= 500:
                return val
    for i in range(len(words) - 1):
        if words[i].isdigit() and words[i + 1] in ("tab", "tabs", "tablet", "tablets", "cap", "caps", "capsule", "capsules", "strip", "strips") and int(words[i]) <= 500:
            return int(words[i])
    return 1

out = []
try:
    f = frappe.form_dict
    q = (f.get("q") or "").strip()
    wh = f.get("warehouse")
    show_zero = f.get("zero") not in ("0", "false")

    meta = frappe.get_meta("Batch")

    def find_f(fn):
        if meta.has_field(fn):
            return fn
        if meta.has_field("custom_" + fn):
            return "custom_" + fn
        return None

    f_exp = find_f("expiry_date")
    f_qty = find_f("batch_qty")
    f_item = "item" if meta.has_field("item") else ("item_code" if meta.has_field("item_code") else None)
    f_iname = find_f("item_name")
    f_mrp = find_f("mrp")
    f_pur = find_f("purchase_rate")
    f_net = find_f("net_rate")
    f_gst = find_f("gst_rate")
    f_hsn = find_f("hsn_code")
    f_upp = find_f("units_per_pack")

    fields = ["name"]
    for field_name in [f_item, f_iname, f_exp, f_qty, f_mrp, f_pur, f_net, f_gst, f_hsn, f_upp]:
        if field_name and field_name not in fields:
            fields.append(field_name)

    filters = {}
    if meta.has_field("disabled"):
        filters["disabled"] = 0

    or_filters = []
    if q:
        if f_item:
            or_filters.append(["Batch", f_item, "like", "%" + q + "%"])
        if f_iname:
            or_filters.append(["Batch", f_iname, "like", "%" + q + "%"])
        or_filters.append(["Batch", "name", "like", "%" + q + "%"])

    order_parts = []
    if f_iname:
        order_parts.append(f_iname + " asc")
    if f_exp:
        order_parts.append(f_exp + " asc")
    order_parts.append("name asc")
    order_by = ", ".join(order_parts)

    rows = frappe.get_all("Batch", filters=filters, or_filters=or_filters if or_filters else None,
        fields=fields, order_by=order_by, limit=500)

    for b in rows:
        item_code = b.get(f_item) if f_item else ""
        item_name = b.get(f_iname) if f_iname else ""
        if not item_name and item_code:
            item_name = frappe.db.get_value("Item", item_code, "item_name") or item_code

        qty = (b.get(f_qty) if f_qty else 0) or 0
        if wh:
            w = wh_qty(b.name, wh)
            if w is not None:
                qty = w
        elif not f_qty or qty == 0:
            try:
                s = frappe.db.sql("""select sum(actual_qty) from `tabStock Ledger Entry`
                    where batch_no = %s and is_cancelled = 0""", (b.name,))
                if s and s[0] and s[0][0] is not None:
                    qty = float(s[0][0])
            except:
                pass

        if qty <= 0 and not show_zero:
            continue

        mrp = (b.get(f_mrp) if f_mrp else 0) or 0
        pur = (b.get(f_pur) if f_pur else 0) or 0
        net = (b.get(f_net) if f_net else pur) or pur or 0
        gst = (b.get(f_gst) if f_gst else 0) or 0
        hsn = (b.get(f_hsn) if f_hsn else "") or ""
        upp = (b.get(f_upp) if f_upp else 1) or 1
        exp = str((b.get(f_exp) if f_exp else "") or "")

        if upp <= 1:
            name_upp = parse_upp_from_name(item_name or item_code)
            if name_upp > 1:
                upp = name_upp
        if upp < 1:
            upp = 1

        if mrp <= 0 and pur > 0:
            mrp = round(pur * (1 + (gst or 0) / 100.0), 2)

        out.append({
            "batch": b.name,
            "item": item_code,
            "name": item_name or item_code or b.name,
            "expiry": exp,
            "qty": qty if qty > 0 else 0,
            "mrp": mrp,
            "purchase_rate": pur,
            "net_rate": net,
            "gst": gst,
            "hsn": hsn,
            "upp": upp
        })

    # Also include items without batches or items that have stock in Bin
    seen_items = set()
    for x in out:
        if x.get("item"):
            seen_items.add(x["item"])

    iq = []
    if q:
        iq = [["Item", "item_name", "like", "%" + q + "%"], ["Item", "item_code", "like", "%" + q + "%"]]
    items = frappe.get_all("Item", filters={"disabled": 0, "is_stock_item": 1}, or_filters=iq if iq else None,
        fields=["name", "item_name", "item_group", "has_batch_no"], order_by="item_name asc", limit=500)
    for it in items:
        if it.name in seen_items:
            continue
        grp = (it.item_group or "").lower()
        if it.item_group != "Drug" and not it.has_batch_no and "drug" not in grp and "med" not in grp:
            continue
        seen_items.add(it.name)

        bin_qty = 0.0
        bin_val = 0.0
        try:
            if wh:
                b_info = frappe.db.get_value("Bin", {"item_code": it.name, "warehouse": wh}, ["actual_qty", "valuation_rate"], as_dict=True)
                if b_info:
                    bin_qty = float(b_info.actual_qty or 0)
                    bin_val = float(b_info.valuation_rate or 0)
            else:
                b_res = frappe.db.sql("select sum(actual_qty), max(valuation_rate) from `tabBin` where item_code = %s", (it.name,))
                if b_res and b_res[0] and b_res[0][0] is not None:
                    bin_qty = float(b_res[0][0] or 0)
                    bin_val = float(b_res[0][1] or 0)
        except:
            pass

        if bin_qty <= 0 and not show_zero:
            continue

        item_mrp = 0
        try:
            p = frappe.db.get_value("Item Price", {"item_code": it.name, "selling": 1, "price_list_rate": [">", 0]}, "price_list_rate")
            if p:
                item_mrp = float(p)
        except:
            pass
        if not item_mrp:
            sr = frappe.db.get_value("Item", it.name, "standard_rate")
            if sr:
                item_mrp = float(sr)

        upp = parse_upp_from_name(it.item_name or it.name)

        out.append({
            "batch": "",
            "item": it.name,
            "name": it.item_name or it.name,
            "expiry": "",
            "qty": bin_qty if bin_qty > 0 else 0,
            "mrp": item_mrp,
            "purchase_rate": bin_val,
            "net_rate": bin_val,
            "gst": 5,
            "hsn": "",
            "upp": upp
        })

except Exception as e:
    frappe.log_error(title="ph_stock_list error", message=frappe.get_traceback())

frappe.response["message"] = {
    "batches": out,
    "products": out
}

# Server Script: ph_stock_save
# type: API
# doctype: -
# event: Before Insert
# api_method: ph_stock_save
# allow_guest: 0
# frequency: All
# disabled: 0

user = frappe.session.user
is_admin = (user == "Administrator")
if not is_admin:
    for r in ["Healthcare Administrator", "System Manager"]:
        if frappe.db.exists("Has Role", {"parent": user, "role": r}):
            is_admin = True
            break
ok = is_admin
if not ok:
    for r in ["Stock User", "Stock Manager", "Accounts User", "Sales User", "Purchase User", "System Manager"]:
        if frappe.db.exists("Has Role", {"parent": user, "role": r}):
            ok = True
            break
if not ok:
    frappe.throw("You don't have access to the pharmacy.")

def num(v):
    try:
        return float(v or 0)
    except:
        return 0.0

def batchify(code):
    # items made from a Medication may not be batch items yet; switch them on (only possible before any stock movement)
    if not frappe.db.get_value("Item", code, "has_batch_no"):
        it = frappe.get_doc("Item", code)
        it.has_batch_no = 1
        it.has_expiry_date = 1
        it.create_new_batch = 0
        it.save(ignore_permissions=True)
    return code

def ensure_dosage_form(form_name):
    if not form_name or not frappe.db.exists("DocType", "Dosage Form"):
        return form_name or "Tablet"
    fn = form_name.strip()
    if not fn:
        return "Tablet"
    if not frappe.db.exists("Dosage Form", fn):
        try:
            df = frappe.new_doc("Dosage Form")
            df.name = fn
            df.flags.name_set = True
            df.dosage_form = fn
            df.insert(ignore_permissions=True, ignore_mandatory=True)
        except:
            pass
    return fn

def ensure_medication_class(cls_name):
    if not cls_name or not frappe.db.exists("DocType", "Medication Class"):
        return cls_name or "Drug"
    cn = cls_name.strip()
    if not cn:
        return "Drug"
    if not frappe.db.exists("Medication Class", cn):
        try:
            mc = frappe.new_doc("Medication Class")
            mc.name = cn
            mc.flags.name_set = True
            mc.medication_class = cn
            mc.insert(ignore_permissions=True, ignore_mandatory=True)
        except:
            pass
    return cn

def ensure_medication(item_code, item_name, form=None, generic=None, mclass=None, strength=None, unit=None):
    if not frappe.db.exists("DocType", "Medication"):
        return None

    nm = (item_name or item_code or "").strip()
    existing = None
    if frappe.db.exists("Medication", nm):
        existing = nm
    elif frappe.db.exists("Medication", {"item": item_code}):
        existing = frappe.db.get_value("Medication", {"item": item_code}, "name")
    elif frappe.db.exists("Medication", {"item_code": item_code}):
        existing = frappe.db.get_value("Medication", {"item_code": item_code}, "name")

    meta_med = frappe.get_meta("Medication")

    # Resolve dosage form
    df_name = ""
    if form:
        df_name = ensure_dosage_form(form)
    elif existing and meta_med.has_field("dosage_form"):
        df_name = frappe.db.get_value("Medication", existing, "dosage_form") or ""
    if not df_name:
        first_form = frappe.get_all("Dosage Form", fields=["name"], limit=1)
        df_name = first_form[0].name if first_form else "Tablet"
        ensure_dosage_form(df_name)

    # Resolve medication class
    cls_name = ""
    if mclass:
        cls_name = ensure_medication_class(mclass)
    elif existing and meta_med.has_field("medication_class"):
        cls_name = frappe.db.get_value("Medication", existing, "medication_class") or ""
    if not cls_name:
        if frappe.db.exists("Medication Class", "Drug"):
            cls_name = "Drug"
        else:
            first_cls = frappe.get_all("Medication Class", fields=["name"], limit=1)
            cls_name = first_cls[0].name if first_cls else "Drug"
            ensure_medication_class(cls_name)

    st_val = num(strength) if strength else 1.0
    uom_val = (unit or "").strip() or "Nos"
    if not frappe.db.exists("UOM", uom_val):
        try:
            frappe.get_doc({"doctype": "UOM", "uom_name": uom_val}).insert(ignore_permissions=True)
        except:
            pass

    gen_val = (generic or "").strip() or nm

    if existing:
        try:
            med = frappe.get_doc("Medication", existing)
            changed = False
            if df_name and meta_med.has_field("dosage_form") and (not med.dosage_form or form):
                med.dosage_form = df_name
                changed = True
            if cls_name and meta_med.has_field("medication_class") and (not med.medication_class or mclass):
                med.medication_class = cls_name
                changed = True
            if generic and meta_med.has_field("generic_name") and (not med.generic_name or med.generic_name == nm):
                med.generic_name = gen_val
                changed = True
            if strength and meta_med.has_field("strength"):
                med.strength = st_val
                changed = True
            if unit and meta_med.has_field("strength_uom"):
                med.strength_uom = uom_val
                changed = True
            if changed:
                med.save(ignore_permissions=True)
            return med.name
        except:
            return existing
    else:
        try:
            med = frappe.new_doc("Medication")
            med.name = nm
            med.flags.name_set = True
            if meta_med.has_field("medication_name"):
                med.medication_name = nm
            if meta_med.has_field("generic_name"):
                med.generic_name = gen_val
            if meta_med.has_field("item"):
                med.item = item_code
            if meta_med.has_field("item_code"):
                med.item_code = item_code
            if df_name and meta_med.has_field("dosage_form"):
                med.dosage_form = df_name
            if cls_name and meta_med.has_field("medication_class"):
                med.medication_class = cls_name
            if meta_med.has_field("strength"):
                med.strength = st_val
            if meta_med.has_field("strength_uom"):
                med.strength_uom = uom_val
            med.flags.ignore_mandatory = True
            med.insert(ignore_permissions=True, ignore_mandatory=True)
            return med.name
        except:
            pass
    return nm

def ensure_item(name, item_group=None, stock_uom=None, form=None, generic=None, mclass=None, strength=None, unit=None):
    grp = item_group or "Drug"
    if not frappe.db.exists("Item Group", grp):
        if frappe.db.exists("Item Group", "Drug"):
            grp = "Drug"
        else:
            grp = frappe.db.get_value("Item Group", {"is_group": 0}, "name") or "All Item Groups"

    uom = stock_uom or "Nos"
    if not frappe.db.exists("UOM", uom):
        try:
            frappe.get_doc({"doctype": "UOM", "uom_name": uom}).insert(ignore_permissions=True)
        except:
            pass

    code = None
    if frappe.db.exists("Item", name):
        code = batchify(name)
    else:
        found = frappe.db.get_value("Item", {"item_name": name}, "name")
        if found:
            code = batchify(found)
        else:
            it = frappe.new_doc("Item")
            it.item_code = name
            it.item_name = name
            it.item_group = grp
            it.stock_uom = uom
            it.is_stock_item = 1
            it.has_batch_no = 1
            it.has_expiry_date = 1
            it.create_new_batch = 0
            it.insert(ignore_permissions=True)
            code = it.name

    ensure_medication(code, name, form=form, generic=generic, mclass=mclass, strength=strength, unit=unit)
    return code

def ensure_batch_fields():
    meta = frappe.get_meta("Batch")
    needed = [
        ("mrp", "MRP", "Currency", "batch_qty"),
        ("units_per_pack", "Units Per Pack", "Int", "mrp"),
        ("purchase_rate", "Purchase Rate", "Currency", "units_per_pack"),
        ("net_rate", "Net Rate", "Currency", "purchase_rate"),
        ("gst_rate", "GST Rate", "Percent", "net_rate"),
        ("hsn_code", "HSN Code", "Data", "gst_rate")
    ]
    created = False
    for fn, label, ftype, after in needed:
        if not (meta.has_field(fn) or meta.has_field("custom_" + fn)):
            try:
                cf = frappe.new_doc("Custom Field")
                cf.dt = "Batch"
                cf.fieldname = fn
                cf.label = label
                cf.fieldtype = ftype
                if after:
                    cf.insert_after = after
                cf.insert(ignore_permissions=True)
                created = True
            except:
                pass
    if created:
        try:
            frappe.clear_cache(doctype="Batch")
        except:
            pass

def ensure_batch(item, batch_in, expiry, hsn, gst, mrp, rate, net, upp):
    try:
        ensure_batch_fields()
    except:
        pass

    bname = (batch_in or "").strip()
    existing = frappe.db.get_value("Batch", {"batch_id": bname, "item": item}, "name")
    if not existing and frappe.db.exists("Batch", bname):
        if frappe.db.get_value("Batch", bname, "item") == item:
            existing = bname

    meta = frappe.get_meta("Batch")
    def set_batch_fields(doc):
        if expiry:
            doc.expiry_date = expiry
        for fn, val in [("hsn_code", hsn), ("gst_rate", gst), ("mrp", mrp),
                        ("purchase_rate", rate), ("net_rate", net), ("units_per_pack", upp)]:
            if meta.has_field(fn):
                doc.set(fn, val)
            if meta.has_field("custom_" + fn):
                doc.set("custom_" + fn, val)

    target_name = bname
    if existing:
        b = frappe.get_doc("Batch", existing)
        set_batch_fields(b)
        b.save(ignore_permissions=True)
        target_name = b.name
    else:
        if frappe.db.exists("Batch", target_name):
            target_name = bname + "-" + item
            n = 1
            while frappe.db.exists("Batch", target_name):
                target_name = bname + "-" + str(n)
                n += 1

        b = frappe.new_doc("Batch")
        b.name = target_name
        b.flags.name_set = True
        b.batch_id = bname
        b.item = item
        set_batch_fields(b)
        b.insert(ignore_permissions=True, ignore_mandatory=True)

    for fn, val in [("hsn_code", hsn), ("gst_rate", gst), ("mrp", mrp),
                    ("purchase_rate", rate), ("net_rate", net), ("units_per_pack", upp)]:
        for fld in (fn, "custom_" + fn):
            try:
                frappe.db.set_value("Batch", target_name, fld, val, update_modified=False)
            except:
                pass

    if mrp > 0:
        try:
            frappe.db.set_value("Item", item, "standard_rate", mrp, update_modified=False)
        except:
            pass

    return target_name

def wh_qty(b, w):
    try:
        r = frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=b, warehouse=w)
        if isinstance(r, (int, float)):
            return float(r)
        if isinstance(r, list):
            return sum(float(x.get("qty") or 0) for x in r)
    except:
        pass
    try:
        s = frappe.db.sql("""select sum(actual_qty) from `tabStock Ledger Entry`
            where batch_no = %s and warehouse = %s and is_cancelled = 0""", (b, w))
        if s and s[0] and s[0][0] is not None:
            return float(s[0][0])
    except:
        pass
    return None

f = frappe.form_dict
product = (f.get("product") or "").strip()
batch_in = (f.get("batch") or "").strip()
wh = f.get("warehouse")
