    val = float(std_rate or 0)
    if val > 0:
        return val
    nm = (name or "").strip().lower()
    cd = (code or "").strip().upper()
    if cd == "CONSULT-GEN" or "consultation" in nm:
        return 100.0
    if "iv fluid" in nm:
