            if tok and frappe.db.exists("Patient Encounter", tok):
                if not rem_enc:
                    rem_enc = tok
                continue
        kept_rem.append(rs)
    clean_remarks = " | ".join(kept_rem)

    charge_amt = 0.0
    charge_name = ""
