        net_rate = float(it.rate or 0)
        if pl_rate > 0:
            base_rate = pl_rate
        elif 0 < disc < 100 and net_rate > 0:
            base_rate = round(net_rate / (1.0 - disc / 100.0), 2)
        else:
            base_rate = net_rate
        if disc <= 0 and base_rate > 0 and net_rate < base_rate - 0.01:
            disc = round((1.0 - net_rate / base_rate) * 100.0, 4)

