def is_ref_free(ref_dt, ref_dn, exclude_inv=""):
    if not ref_dt or not ref_dn or not frappe.db.exists(ref_dt, ref_dn):
        return False
    try:
        if int(frappe.db.get_value(ref_dt, ref_dn, "invoiced") or 0) == 1:
            return False
    except Exception:
        pass
    try:
        if ref_dt == "Patient Appointment" and int(frappe.db.get_value(ref_dt, ref_dn, "fee_valid") or 0) == 1:
            return False
    except Exception:
        pass
    try:
        existing_rows = frappe.db.sql("""
            select sii.parent
            from `tabSales Invoice Item` sii
            join `tabSales Invoice` si on si.name = sii.parent
            where sii.reference_dt = %s
              and sii.reference_dn = %s
              and si.docstatus < 2
              and ifnull(si.is_return, 0) = 0
              and si.name != %s
            limit 1
        """, (ref_dt, ref_dn, exclude_inv or ""))
        if existing_rows:
            return False
    except Exception:
        pass
    return True

