        av = frappe.db.get_value("Patient Appointment", appointment, ["patient", "practitioner"], as_dict=True) or {}
        if not patient and av.get("patient"):
            patient = av.get("patient")
        if not practitioner and av.get("practitioner"):
            practitioner = av.get("practitioner")
        if not encounter and frappe.db.exists("DocType", "Patient Encounter"):
            enc_hits = frappe.get_all(
                "Patient Encounter",
                filters={"appointment": appointment, "docstatus": ["<", 2]},
                fields=["name"],
                order_by="docstatus desc, modified desc",
                limit=1,
            )
            if enc_hits:
                encounter = enc_hits[0].name

    # Resolve Customer (prefer Patient's linked Customer if Patient was chosen cleanly)
    customer = ""
    pat_name_resolved = ""
    pat_had_cust = False
    if patient and frappe.db.exists("Patient", patient):
        pat_vals = frappe.db.get_value("Patient", patient, ["patient_name", "customer"], as_dict=True)
        pat_name_resolved = (pat_vals.get("patient_name") or "") if pat_vals else ""
        if pat_vals and pat_vals.get("customer") and frappe.db.exists("Customer", pat_vals.get("customer")):
            pat_had_cust = True
            if not customer_input or customer_input == pat_vals.get("patient_name") or customer_input == pat_vals.get("customer"):
                customer = pat_vals.get("customer")

    if not customer and customer_input:
        if frappe.db.exists("Customer", customer_input):
            customer = customer_input
        else:
            matched = frappe.db.get_value("Customer", {"customer_name": customer_input, "disabled": 0}, "name")
            if matched:
                customer = matched
            else:
                c = frappe.new_doc("Customer")
                c.customer_name = customer_input
                c.customer_group = frappe.db.get_value("Customer Group", {"is_group": 0}, "name")
                c.territory = frappe.db.get_value("Territory", {"is_group": 0}, "name")
                c.customer_type = "Individual"
                c.insert(ignore_permissions=True)
                customer = c.name

    if not customer and pat_name_resolved:
        matched_p = frappe.db.get_value("Customer", {"customer_name": pat_name_resolved, "disabled": 0}, "name")
        if matched_p:
            customer = matched_p
        else:
            c = frappe.new_doc("Customer")
            c.customer_name = pat_name_resolved
            c.customer_group = frappe.db.get_value("Customer Group", {"is_group": 0}, "name")
            c.territory = frappe.db.get_value("Territory", {"is_group": 0}, "name")
            c.customer_type = "Individual"
            c.insert(ignore_permissions=True)
            customer = c.name

    if patient and customer and not pat_had_cust and customer not in ["Walk-in Customer", "Walk-in"]:
        if not customer_input or customer_input == pat_name_resolved:
            try:
                frappe.db.set_value("Patient", patient, "customer", customer, update_modified=False)
            except Exception:
                pass

    if not customer:
        for fallback_name in ["Walk-in Customer", "Walk-in"]:
            if frappe.db.exists("Customer", fallback_name):
                customer = fallback_name
                break
        if not customer:
            c = frappe.new_doc("Customer")
            c.customer_name = "Walk-in Customer"
            c.customer_group = frappe.db.get_value("Customer Group", {"is_group": 0}, "name")
            c.territory = frappe.db.get_value("Territory", {"is_group": 0}, "name")
            c.customer_type = "Individual"
            c.insert(ignore_permissions=True)
            customer = c.name

    # Resolve or create generic fallback Service Item for custom ad-hoc service lines
    def resolve_misc_service_item(cached):
        if cached:
            return cached
        for candidate in ["MISC-SERVICE", "CLINIC-SERVICE"]:
            if frappe.db.exists("Item", candidate):
                return candidate
        svc_group = "Services"
        if not frappe.db.exists("Item Group", svc_group):
            svc_group = frappe.db.get_value("Item Group", {"is_group": 0}, "name") or "All Item Groups"
        uom = "Nos"
        if not frappe.db.exists("UOM", uom):
            uom = frappe.db.get_value("UOM", {}, "name") or "Unit"
        it = frappe.new_doc("Item")
        it.item_code = "MISC-SERVICE"
        it.item_name = "Clinic Service / Procedure"
        it.item_group = svc_group
        it.stock_uom = uom
        it.is_stock_item = 0
        it.is_sales_item = 1
        it.insert(ignore_permissions=True)
        return it.name

    if updating_draft:
        si = frappe.get_doc("Sales Invoice", amend_invoice)
        si.items = []
        si.taxes = []
        si.payments = []
        si.is_pos = 0
        si.remarks = ""
    else:
        si = frappe.new_doc("Sales Invoice")
        if amend_from:
            si.amended_from = amend_from

    si.customer = customer
    si.company = company
    si.posting_date = posting_date
    si.set_posting_time = 1
    # General / miscellaneous invoice does not deduct pharmacy batch stock
    si.update_stock = 0
    si.ignore_pricing_rule = 1

    if si.meta.has_field("patient"):
        si.patient = patient if (patient and frappe.db.exists("Patient", patient)) else None

    if si.meta.has_field("patient_name") and pat_name_resolved:
        si.patient_name = pat_name_resolved

    if si.meta.has_field("ref_practitioner"):
        si.ref_practitioner = practitioner or None

    if si.meta.has_field("practitioner"):
        si.practitioner = practitioner or None

    if appointment and si.meta.has_field("appointment") and frappe.db.exists("Patient Appointment", appointment):
        si.appointment = appointment

    if encounter and frappe.db.exists("Patient Encounter", encounter):
        for enc_fld in ("encounter", "patient_encounter"):
            if si.meta.has_field(enc_fld):
                si.set(enc_fld, encounter)

    item_fetch_fields = ["item_name", "stock_uom"]
    try:
        item_meta_doc = frappe.get_meta("Item")
        if item_meta_doc.has_field("item_group"):
            item_fetch_fields.append("item_group")
        if item_meta_doc.has_field("is_stock_item"):
            item_fetch_fields.append("is_stock_item")
    except Exception:
        pass
    has_med_item = False
    has_med_item_code = False
    has_mli_dt = False
    try:
        if frappe.db.exists("DocType", "Medication"):
            med_meta = frappe.get_meta("Medication")
            has_med_item = med_meta.has_field("item")
            has_med_item_code = med_meta.has_field("item_code")
        has_mli_dt = bool(frappe.db.exists("DocType", "Medication Linked Item"))
    except Exception:
        pass

    misc_item_code = ""
    line_pricing = []
    has_drug_line = False
    has_nondrug_line = False
    for ln in lines:
        item_code = (ln.get("item_code") or "").strip()
        custom_name = (ln.get("item_name") or "").strip()
        desc = (ln.get("description") or "").strip()
        qty = num(ln.get("qty"))
        rate = num(ln.get("rate"))
        disc = num(ln.get("disc"))

        if qty <= 0:
            frappe.throw("Every line item must have quantity greater than zero.")
        if rate < 0:
            frappe.throw("Rate cannot be negative.")
        if disc < 0:
            disc = 0.0
        elif disc > 100:
            disc = 100.0

        resolved_code = ""
        if item_code and frappe.db.exists("Item", item_code):
            resolved_code = item_code
        elif custom_name:
            matched_item = frappe.db.get_value("Item", {"item_name": custom_name, "is_stock_item": 0, "disabled": 0}, "name")
            if matched_item:
                resolved_code = matched_item
            else:
                misc_item_code = resolve_misc_service_item(misc_item_code)
                resolved_code = misc_item_code
        else:
            frappe.throw("Each line item must specify an item or service name.")

        item_meta_vals = frappe.db.get_value("Item", resolved_code, item_fetch_fields, as_dict=True) or {}
        final_name = custom_name or item_meta_vals.get("item_name") or resolved_code
        final_desc = desc or final_name
        uom = item_meta_vals.get("stock_uom") or "Nos"
        ig = str(item_meta_vals.get("item_group") or "").strip().lower()
        is_stock = int(item_meta_vals.get("is_stock_item") or 0)
        med_linked = False
        if resolved_code and resolved_code not in ["MISC-SERVICE", "CLINIC-SERVICE"] and not is_stock:
            try:
                if has_med_item and frappe.db.exists("Medication", {"item": resolved_code}):
                    med_linked = True
                elif has_med_item_code and frappe.db.exists("Medication", {"item_code": resolved_code}):
                    med_linked = True
                elif has_mli_dt and frappe.db.exists("Medication Linked Item", {"item": resolved_code}):
                    med_linked = True
            except Exception:
                pass
        line_txt = (resolved_code + " " + final_name + " " + ig).lower()
        is_drug_line = ("consult" not in line_txt) and (
            is_stock == 1
            or med_linked
            or ("drug" in ig)
            or ("medic" in ig)
            or ("pharm" in ig)
            or ("drug" in line_txt)
            or ("medic" in line_txt)
            or ("pharm" in line_txt)
            or ("tablet" in line_txt)
            or ("capsule" in line_txt)
            or ("syrup" in line_txt)
        )
        if is_drug_line:
            has_drug_line = True
        else:
            has_nondrug_line = True

        disc_unit = rate * (disc / 100.0)
        net_unit = rate - disc_unit

        line_pricing.append({
            "item_name": final_name,
            "description": final_desc,
            "price_list_rate": rate,
            "discount_percentage": disc,
            "discount_amount": disc_unit,
            "rate": net_unit
        })

        si.append("items", {
            "item_code": resolved_code,
            "item_name": final_name,
            "description": final_desc,
            "qty": qty,
            "uom": uom,
            "stock_uom": uom,
            "conversion_factor": 1,
            "price_list_rate": rate,
            "margin_type": "",
            "margin_rate_or_amount": 0,
            "discount_percentage": disc,
            "discount_amount": disc_unit,
            "rate": net_unit,
            "income_account": co.default_income_account if co else None,
            "cost_center": co.cost_center if co else None
        })

    is_drug_only_inv = bool(line_pricing) and has_drug_line and (not has_nondrug_line)
    remark_parts = []
    if practitioner:
        prac_name = frappe.db.get_value("Healthcare Practitioner", practitioner, "practitioner_name") or practitioner
        remark_parts.append("Doctor: " + prac_name)
    if appointment and not is_drug_only_inv and frappe.db.exists("Patient Appointment", appointment):
        remark_parts.append("Consultation: " + appointment)
    if encounter and frappe.db.exists("Patient Encounter", encounter):
        remark_parts.append("Encounter: " + encounter)
    if remarks:
        remark_parts.append(remarks)
    if remark_parts:
        si.remarks = " | ".join(remark_parts)

    si.run_method("set_missing_values")
    # Re-apply explicit item names, descriptions, and discounted rates after set_missing_values().
    si.ignore_pricing_rule = 1
    for idx in range(len(line_pricing)):
        row = si.items[idx]
        lp = line_pricing[idx]
        row.item_name = lp["item_name"]
        row.description = lp["description"]
        row.price_list_rate = lp["price_list_rate"]
        row.margin_type = ""
        row.margin_rate_or_amount = 0
        row.discount_percentage = lp["discount_percentage"]
        row.discount_amount = lp["discount_amount"]
        row.rate = lp["rate"]

    if not si.debit_to and co:
        si.debit_to = co.default_receivable_account

    if si.items and not is_drug_only_inv:
        exclude_name = amend_invoice if updating_draft else ""
        # Never set reference_dt="Patient Encounter" on Sales Invoice Item: Marley Healthcare's
        # Sales Invoice validation locks double/insert+submit encounter references even when only drugs
        # or Fee Validity touched the encounter. Keep Encounter linked via header fields & remarks.
        can_ref_appt = is_ref_free("Patient Appointment", appointment, exclude_name) if appointment else False
        if can_ref_appt:
            try:
                si_item_meta = frappe.get_meta("Sales Invoice Item")
                if si_item_meta.has_field("reference_dt") and si_item_meta.has_field("reference_dn"):
                    si.items[0].reference_dt = "Patient Appointment"
                    si.items[0].reference_dn = appointment
            except Exception:
                pass

    if charge_amt > 0:
        charge_acc = co.default_income_account if co else None
        if not charge_acc:
            charge_acc = frappe.db.get_value("Account", {"account_type": "Income Account", "company": company, "is_group": 0}, "name")
        if not charge_acc:
            charge_acc = frappe.db.get_value("Account", {"account_name": ["like", "%Income%"], "company": company, "is_group": 0}, "name")
        si.append("taxes", {
            "charge_type": "Actual",
            "account_head": charge_acc,
            "description": charge_name or "Additional Charge",
            "tax_amount": charge_amt,
            "cost_center": co.cost_center if co else None
        })

    si.run_method("calculate_taxes_and_totals")

    pay_amt = si.rounded_total if (si.rounded_total is not None and not si.disable_rounded_total) else si.grand_total
    paid = False
    note = ""

    if not save_draft and mode and mode != "Credit":
        pos_acc = frappe.db.get_value("Mode of Payment Account", {"parent": mode, "company": company}, "default_account")
        if pos_acc:
            si.is_pos = 1
            si.append("payments", {
                "mode_of_payment": mode,
                "account": pos_acc,
                "amount": pay_amt
            })
            paid = True

    if updating_draft:
        si.save(ignore_permissions=True)
    else:
        si.insert(ignore_permissions=True)

    if not save_draft:
        si.submit()
        if appointment and not is_drug_only_inv and frappe.db.exists("Patient Appointment", appointment):
            try:
                frappe.db.set_value("Patient Appointment", appointment, "invoiced", 1, update_modified=False)
            except Exception:
                pass
        if not paid and mode and mode != "Credit" and (pay_amt or 0) > 0:
            try:
                pe = frappe.call("erpnext.accounts.doctype.payment_entry.payment_entry.get_payment_entry",
                    dt="Sales Invoice", dn=si.name)
                pe.mode_of_payment = mode
                pe.posting_date = posting_date
                pe.reference_no = si.name
                pe.reference_date = posting_date
                pe.insert(ignore_permissions=True)
                pe.submit()
                paid = True
            except Exception:
                note = "Invoice submitted, but payment entry was not created automatically."

    frappe.response["message"] = {
        "invoice": si.name,
        "customer": si.customer,
        "patient": si.get("patient") if si.meta.has_field("patient") else patient,
        "appointment": appointment,
        "encounter": encounter,
        "total": pay_amt,
        "docstatus": si.docstatus,
        "paid": paid,
        "mode": mode,
        "note": note
    }

# Server Script: tpl_save
# type: API
# doctype: -
# event: Before Insert
# api_method: tpl_save
# allow_guest: 0
# frequency: All
# disabled: 0

user = frappe.session.user
ok = (user == "Administrator")
if not ok:
    for r in ["Healthcare Administrator", "System Manager", "Physician"]:
        if frappe.db.exists("Has Role", {"parent": user, "role": r}):
            ok = True
            break
if not ok:
    frappe.throw("Only doctors can save treatment templates.")

if not frappe.db.exists("DocType", "Clinic Treatment Template"):
    frappe.throw("Clinic Treatment Template DocType is not installed yet. Run bench migrate.")

f = frappe.form_dict
name = (f.get("template_name") or "").strip()
if not name:
    frappe.throw("Enter a template name.")
overwrite = f.get("overwrite") == "1" or f.get("overwrite") is True

def clean_list(raw):
    out = []
    seen = set()
    for item in (raw or []):
        val = str(item or "").strip()
        if not val:
            continue
        k = val.lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(val)
    return out

complaints = clean_list(json.loads(f.get("symptoms") or "[]"))
diagnosis = clean_list(json.loads(f.get("diagnosis") or "[]"))
raw_labs = clean_list(json.loads(f.get("labs") or "[]"))
raw_drugs = json.loads(f.get("drugs") or "[]")
notes = (f.get("notes") or "").strip()

labs = []
has_lab_dt = frappe.db.exists("DocType", "Lab Test Template")
lt_meta = frappe.get_meta("Lab Test Template") if has_lab_dt else None
for lt_val in raw_labs:
    lt_name = lt_val
    if has_lab_dt:
        lt_name = frappe.db.get_value("Lab Test Template", lt_val, "name")
        if not lt_name and lt_meta:
            for fld in ("item", "item_code", "lab_test_name", "lab_test_code"):
                if lt_meta.has_field(fld):
                    try:
                        lt_name = frappe.db.get_value("Lab Test Template", {fld: lt_val}, "name")
                        if lt_name:
                            break
                    except Exception:
                        pass
        if not lt_name:
            frappe.throw("Lab test '" + lt_val + "' was not found in Lab Test Template. Please select an existing lab test.")
    if lt_name not in labs:
        labs.append(lt_name)

has_med_dt = frappe.db.exists("DocType", "Medication")
meta_med = frappe.get_meta("Medication") if has_med_dt else None
has_med_name = meta_med.has_field("medication_name") if meta_med else False
has_med_item = meta_med.has_field("item") if meta_med else False
has_med_item_code = meta_med.has_field("item_code") if meta_med else False
has_mli_dt = frappe.db.exists("DocType", "Medication Linked Item")

drugs = []
seen_drugs = set()
for dr in (raw_drugs or []):
    if isinstance(dr, str):
        dr = {"drug": dr}
    elif not isinstance(dr, dict):
        continue
    dname = (dr.get("drug") or dr.get("drug_code") or dr.get("medication") or dr.get("item") or "").strip()
    if not dname:
        continue
    if has_med_dt:
        med = frappe.db.get_value("Medication", dname, "name")
        if not med and has_med_name:
            med = frappe.db.get_value("Medication", {"medication_name": dname}, "name")
        if not med and has_med_item:
            med = frappe.db.get_value("Medication", {"item": dname}, "name")
        if not med and has_med_item_code:
            med = frappe.db.get_value("Medication", {"item_code": dname}, "name")
        if not med and has_mli_dt:
            try:
                med = frappe.db.get_value("Medication Linked Item", {"item": dname}, "parent")
            except Exception:
                med = None
        if not med:
            frappe.throw("Medication '" + dname + "' is not available in the Medication list. Please select an existing medication.")
        dname = med
    dk = dname.lower()
    if dk in seen_drugs:
        continue
    seen_drugs.add(dk)
    drugs.append({
        "drug": dname,
        "form": (dr.get("form") or dr.get("dosage_form") or "").strip(),
        "dosage": (dr.get("dosage") or "").strip(),
        "period": (dr.get("period") or "").strip(),
        "comment": (dr.get("comment") or "").strip(),
    })

if not (complaints or diagnosis or drugs or labs or notes):
    frappe.throw("Add at least one complaint, diagnosis, medicine, lab test, or note before saving a template.")

exists = frappe.db.exists("Clinic Treatment Template", name)
if exists and not overwrite:
    frappe.throw("A template named '" + name + "' already exists. Confirm overwrite or choose another name.")

prac = (f.get("practitioner") or "").strip()
if prac and not frappe.db.exists("Healthcare Practitioner", prac):
    prac = ""

parts = []
if complaints:
    parts.append("Complaints: " + ", ".join(complaints[:3]) + ("..." if len(complaints) > 3 else ""))
if diagnosis:
    parts.append("Diagnosis: " + ", ".join(diagnosis[:3]) + ("..." if len(diagnosis) > 3 else ""))
if drugs:
    parts.append(str(len(drugs)) + " medicine" + ("s" if len(drugs) != 1 else ""))
if labs:
    parts.append(str(len(labs)) + " lab" + ("s" if len(labs) != 1 else ""))
if notes:
    parts.append("Notes")
summary = " | ".join(parts)

payload = {
    "complaints": complaints,
    "diagnosis": diagnosis,
    "drugs": drugs,
    "labs": labs,
    "notes": notes,
}

if exists:
    doc = frappe.get_doc("Clinic Treatment Template", name)
else:
    doc = frappe.new_doc("Clinic Treatment Template")
    doc.template_name = name

doc.practitioner = prac or ""
doc.is_active = 1
doc.notes = notes
doc.summary = summary
doc.template_json = json.dumps(payload)

if exists:
    doc.save(ignore_permissions=True)
else:
    doc.insert(ignore_permissions=True)
frappe.db.commit()

frappe.response["message"] = {
    "template": {
        "name": doc.name,
        "template_name": doc.template_name,
        "practitioner": doc.practitioner or "",
        "summary": summary,
        "complaints": complaints,
        "diagnosis": diagnosis,
        "drugs": drugs,
        "labs": labs,
        "notes": notes,
    }
}

# Server Script: fee_list
# type: API
# doctype: -
# event: Before Insert
# api_method: fee_list
# allow_guest: 0
# frequency: All
# disabled: 0

user = frappe.session.user
is_admin = (user == "Administrator")
if not is_admin:
    for r in ["Healthcare Administrator", "System Manager"]:
        if frappe.db.exists("Has Role", {"parent": user, "role": r}):
            is_admin = True
            break

ok = is_admin
if not ok:
    for r in ["Physician", "Accounts Manager", "Accounts User", "Sales User", "Stock Manager", "Stock User"]:
        if frappe.db.exists("Has Role", {"parent": user, "role": r}):
            ok = True
            break
if not ok:
    frappe.throw("You don't have permission to view fee invoices.")

today_str = str(frappe.utils.today())
date = (frappe.form_dict.get("date") or "").strip() or today_str
try:
    frappe.utils.getdate(date)
except Exception:
    frappe.throw("Invalid invoice date.")

status_filter = (frappe.form_dict.get("status") or "all").strip().lower()
if status_filter not in ("all", "submitted", "draft"):
    status_filter = "all"

docstatus_cond = "si.docstatus = 1" if status_filter == "submitted" else ("si.docstatus = 0" if status_filter == "draft" else "si.docstatus < 2")

si_meta = None
try:
    si_meta = frappe.get_meta("Sales Invoice")
except Exception:
    si_meta = None

opt_si_cols = []
for c in ("patient", "patient_name", "ref_practitioner", "practitioner", "set_warehouse", "posting_time", "outstanding_amount"):
    if si_meta and si_meta.has_field(c):
        opt_si_cols.append("si.`" + c + "`")

extra_select = (", " + ", ".join(opt_si_cols)) if opt_si_cols else ""
rows = frappe.db.sql("""
    SELECT si.name, si.customer, si.customer_name, si.rounded_total, si.grand_total,
           si.docstatus, si.is_return, si.return_against, si.update_stock, si.remarks""" + extra_select + """
    FROM `tabSales Invoice` si
    WHERE si.posting_date = %(date)s
      AND """ + docstatus_cond + """
      AND ifnull(si.update_stock, 0) = 0
    ORDER BY si.docstatus DESC, si.modified DESC
    LIMIT 200
""", {"date": date}, as_dict=True)

drug_codes = set()
try:
    if frappe.db.exists("DocType", "Medication"):
        med_meta = frappe.get_meta("Medication")
        for mf in ("item", "item_code"):
            if med_meta.has_field(mf):
                for mr in frappe.get_all("Medication", fields=[mf], limit=2000):
                    if mr.get(mf):
                        drug_codes.add(mr.get(mf))
    if frappe.db.exists("DocType", "Medication Linked Item"):
        mli_meta = frappe.get_meta("Medication Linked Item")
        if mli_meta.has_field("item"):
            for mr in frappe.get_all("Medication Linked Item", fields=["item"], limit=2000):
                if mr.get("item"):
                    drug_codes.add(mr.get("item"))
except Exception:
    pass

inv_names = [r.name for r in rows if r.get("name")]
items_by_parent = {}
item_codes = []
seen_item_codes = set()
if inv_names:
    sii_fields = ["parent", "item_code", "item_name", "description"]
    try:
        sii_meta = frappe.get_meta("Sales Invoice Item")
        for opt_f in ("batch_no", "item_group", "is_stock_item", "reference_dt"):
            if sii_meta.has_field(opt_f):
                sii_fields.append(opt_f)
    except Exception:
        pass
    for it in frappe.get_all("Sales Invoice Item", filters={"parent": ["in", inv_names]}, fields=sii_fields, order_by="idx asc", limit=1500):
        items_by_parent.setdefault(it.parent, []).append(it)
        ic = str(it.get("item_code") or "").strip()
        if ic and ic not in seen_item_codes:
            seen_item_codes.add(ic)
            item_codes.append(ic)

item_meta_map = {}
if item_codes:
    it_fields = ["name", "item_name"]
    try:
        it_meta = frappe.get_meta("Item")
        for opt_f in ("item_group", "is_stock_item"):
            if it_meta.has_field(opt_f):
                it_fields.append(opt_f)
    except Exception:
        pass
    try:
        for im in frappe.get_all("Item", filters={"name": ["in", item_codes]}, fields=it_fields, limit=1500):
            item_meta_map[im.name] = im
    except Exception:
        pass

prac_ids = []
seen_pracs = set()
pat_ids = []
seen_pats = set()
for r in rows:
    pr = str(r.get("ref_practitioner") or r.get("practitioner") or "").strip()
    if pr and pr not in seen_pracs:
        seen_pracs.add(pr)
        prac_ids.append(pr)
    pt = str(r.get("patient") or "").strip()
    if pt and pt not in seen_pats:
        seen_pats.add(pt)
        pat_ids.append(pt)

prac_map = {}
if prac_ids:
    try:
        for pr in frappe.get_all("Healthcare Practitioner", filters={"name": ["in", prac_ids]}, fields=["name", "practitioner_name"], limit=200):
            prac_map[pr.name] = pr.get("practitioner_name") or pr.name
    except Exception:
        pass

pat_map = {}
if pat_ids:
    try:
        for p in frappe.get_all("Patient", filters={"name": ["in", pat_ids]}, fields=["name", "patient_name", "mobile"], limit=500):
            pat_map[p.name] = p
    except Exception:
        pass

invoices = []
for r in rows:
    if int(r.get("update_stock") or 0) == 1:
        continue
    inv_items = items_by_parent.get(r.name, [])
    has_drug = False
    all_drug = bool(inv_items)
    has_consult = False
    item_labels = []
    for it in inv_items:
        ic = str(it.get("item_code") or "").strip()
        im = item_meta_map.get(ic) or {}
        ig = str(it.get("item_group") or im.get("item_group") or "").strip().lower()
        is_stock = int(im.get("is_stock_item") or it.get("is_stock_item") or 0)
        has_batch = bool(str(it.get("batch_no") or "").strip())
        rdt = str(it.get("reference_dt") or "").strip()
        disp_name = str(it.get("item_name") or im.get("item_name") or ic or "").strip()
        row_txt = (" ".join([ic, disp_name, str(it.get("description") or ""), ig])).lower()

        is_drug_row = (
            rdt == "Drug Prescription"
            or has_batch
            or is_stock == 1
            or (bool(ic) and ic in drug_codes)
            or ("drug" in ig)
            or ("medic" in ig)
            or ("pharm" in ig)
            or ("consult" not in row_txt and ("drug" in row_txt or "medic" in row_txt or "pharm" in row_txt or "tablet" in row_txt or "capsule" in row_txt or "syrup" in row_txt))
        )
        is_consult_row = (not is_drug_row) and (
            ("consult" in row_txt)
            or ("opd" in row_txt)
            or ("fee" in row_txt)
            or ("doctor" in row_txt)
        )
        if is_drug_row:
            has_drug = True
        else:
            all_drug = False
            if disp_name and disp_name not in item_labels:
                item_labels.append(disp_name)
        if is_consult_row:
            has_consult = True

    has_wh = bool(str(r.get("set_warehouse") or "").strip())
    if all_drug:
        continue
    if (has_drug or has_wh) and not has_consult:
        continue

    pt_id = str(r.get("patient") or "").strip()
    p_obj = pat_map.get(pt_id) or {}
    disp_cust = (
        str(r.get("patient_name") or "").strip()
        or str(p_obj.get("patient_name") or "").strip()
        or str(r.get("customer_name") or "").strip()
        or str(r.get("customer") or "").strip()
    )
    pr_id = str(r.get("ref_practitioner") or r.get("practitioner") or "").strip()
    pr_name = prac_map.get(pr_id, "")
    if not pr_name and r.get("remarks"):
        for rpart in str(r.get("remarks") or "").split(" | "):
            rs = rpart.strip()
            if rs.startswith("Doctor: "):
                pr_name = rs[len("Doctor: "):].strip()
                break

    raw_tot = r.get("rounded_total") if r.get("rounded_total") not in (None, 0) else r.get("grand_total")
    tot = abs(float(raw_tot or 0))
    invoices.append({
        "name": r.name,
        "customer": disp_cust,
        "patient": pt_id,
        "mobile": str(p_obj.get("mobile") or ""),
        "practitioner_name": pr_name,
        "items_summary": ", ".join(item_labels[:4]) + ("…" if len(item_labels) > 4 else ""),
        "total": round(tot, 2),
        "outstanding": round(float(r.get("outstanding_amount") or 0), 2),
        "time": str(r.get("posting_time") or "")[:5],
        "docstatus": int(r.get("docstatus") or 0),
        "is_return": int(r.get("is_return") or 0),
        "return_against": r.get("return_against") or "",
    })

frappe.response["message"] = {
    "invoices": invoices,
    "today": today_str,
    "is_admin": is_admin,
}
